import{_ as t,o as s,c as a,a6 as i}from"./chunks/framework.BJFjZBwW.js";const m=JSON.parse('{"title":"Configuration portal HTTP API","description":"","frontmatter":{},"headers":[],"relativePath":"upload/portal-api.md","filePath":"upload/portal-api.md","lastUpdated":1779562908000}'),d={name:"upload/portal-api.md"};function n(o,e,r,l,p,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="configuration-portal-http-api" tabindex="-1">Configuration portal HTTP API <a class="header-anchor" href="#configuration-portal-http-api" aria-label="Permalink to &quot;Configuration portal HTTP API&quot;">​</a></h1><p>This page documents the HTTP form fields accepted by the on-device WiFi configuration portal so that companion apps, provisioning scripts, and Home Assistant flows can integrate without reading firmware source.</p><p>The portal is implemented on top of <a href="https://github.com/h2zero/WiFiManager" target="_blank" rel="noreferrer">h2zero&#39;s WiFiManager fork</a> and the field declarations live in <code>main/main.cpp</code> (see <code>setup_wifimanager</code>).</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST http://&lt;portal-ip&gt;/wifisave</span></span>
<span class="line"><span>Content-Type: application/x-www-form-urlencoded</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>When the portal is active (no saved credentials, or trigger pressed at boot) the device exposes a soft-AP — see <a href="./portal.html">Portal</a> for SSID/password rules.</p><h2 id="form-fields" tabindex="-1">Form fields <a class="header-anchor" href="#form-fields" aria-label="Permalink to &quot;Form fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source declaration</th><th>Persisted?</th></tr></thead><tbody><tr><td><code>s</code></td><td>SSID</td><td>WiFiManager built-in</td><td>yes</td></tr><tr><td><code>p</code></td><td>WiFi PSK</td><td>WiFiManager built-in</td><td>yes</td></tr><tr><td><code>server</code></td><td>MQTT host (≤ 64)</td><td><code>custom_mqtt_server</code></td><td>yes, if non-empty</td></tr><tr><td><code>port</code></td><td>MQTT port</td><td><code>custom_mqtt_port</code></td><td>yes, if non-empty</td></tr><tr><td><code>user</code></td><td>MQTT username</td><td><code>custom_mqtt_user</code></td><td>yes, if non-empty</td></tr><tr><td><code>pass</code></td><td>MQTT password</td><td><code>custom_mqtt_pass</code></td><td>yes, if non-empty <em>and</em> value differs from the compile-time <code>MQTT_PASS</code> sentinel</td></tr><tr><td><code>secure</code></td><td><code>0</code> / <code>1</code></td><td><code>custom_mqtt_secure</code></td><td>yes (always)</td></tr><tr><td><code>validate</code></td><td><code>0</code> / <code>1</code></td><td><code>custom_validate_cert</code></td><td>yes (always)</td></tr><tr><td><code>cert</code></td><td>PEM (≤ 4096 B)</td><td><code>custom_mqtt_cert</code></td><td>yes, if length &gt; <code>MIN_CERT_LENGTH</code></td></tr><tr><td><code>ota_cert</code></td><td>PEM (≤ 4096 B)</td><td><code>custom_ota_server_cert</code></td><td>yes, if length &gt; <code>MIN_CERT_LENGTH</code></td></tr><tr><td><code>client_cert</code></td><td>PEM</td><td><code>custom_client_cert</code> (signed-client builds only)</td><td>yes, if length &gt; <code>MIN_CERT_LENGTH</code></td></tr><tr><td><code>client_key</code></td><td>PEM</td><td><code>custom_client_key</code> (signed-client builds only)</td><td>yes, if length &gt; <code>MIN_CERT_LENGTH</code></td></tr><tr><td><code>topic</code></td><td>MQTT base topic</td><td><code>custom_mqtt_topic</code></td><td>yes, if non-empty (trailing <code>/</code> added if missing)</td></tr><tr><td><code>name</code></td><td>Gateway name</td><td><code>custom_gateway_name</code></td><td>yes, if non-empty</td></tr><tr><td><code>ota</code></td><td>OTA / WebUI password</td><td><code>custom_ota_pass</code></td><td>yes, if non-empty</td></tr></tbody></table><h2 id="empty-field-semantics" tabindex="-1">Empty-field semantics <a class="header-anchor" href="#empty-field-semantics" aria-label="Permalink to &quot;Empty-field semantics&quot;">​</a></h2><p>Empty <code>server</code> / <code>port</code> / <code>user</code> / <code>topic</code> / <code>name</code> / <code>ota</code> values are <strong>ignored</strong> rather than persisted. This means a partial POST (e.g. WiFi-only) preserves any pre-flashed defaults instead of clearing them. To intentionally clear a field, this portal API does not currently support it — re-flash with new build defaults or use the WebUI.</p><p>The <code>pass</code> field combines the empty-check with a sentinel guard: the firmware persists the form value only when it is non-empty <em>and</em> differs from the compile-time <code>MQTT_PASS</code> sentinel. The sentinel branch prevents an unmodified form (which echoes back the default) from overwriting a stored password; the non-empty branch prevents a partial POST from wiping it.</p><h2 id="response-and-ap-teardown" tabindex="-1">Response and AP teardown <a class="header-anchor" href="#response-and-ap-teardown" aria-label="Permalink to &quot;Response and AP teardown&quot;">​</a></h2><p>After processing the POST, WiFiManager returns a small success page and then tears down the soft-AP to attempt joining the configured station network. The teardown happens quickly enough that the TCP socket may be reset before the HTTP response is fully flushed to the client. Companion apps should:</p><ul><li>Treat a connection reset immediately after the POST as a likely-success signal, not a failure.</li><li>Verify provisioning by checking for the device on the target network or for its first MQTT LWT message rather than relying on the HTTP response.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s=my-ssid&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;p=my-psk&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;server=192.168.1.10&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;port=1883&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;name=kitchen-omg&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ota=mySecret123&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-urlencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;topic=home/&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://192.168.4.1/wifisave</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div>`,16)])])}const u=t(d,[["render",n]]);export{m as __pageData,u as default};
